<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{FeeRepository,SettingsRepository,StudentRepository};use App\Services\FeeAutomationService;use App\Support\Flash;
final class FeeAutomationController extends AdminPageController{
private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}
public function index(Request$q):Response{$i=$this->i();$settings=$this->app->database()->query('SELECT * FROM fee_settings WHERE institute_id=:i',['i'=>$i])->fetch()?:[];$runs=$this->app->database()->query('SELECT r.*,u.name triggered_by_name FROM fee_generation_runs r LEFT JOIN users u ON u.id=r.triggered_by WHERE r.institute_id=:i ORDER BY r.created_at DESC LIMIT 24',['i'=>$i])->fetchAll();return$this->view('fees/automation',['pageTitle'=>'Fee Automation','activeMenu'=>'fees','activeSubmenu'=>'fee-automation','institute'=>(new SettingsRepository($this->app->database()))->institute(),'settings'=>$settings,'runs'=>$runs]);}
public function save(Request$q):Response{$day=(int)$q->input('generation_day');$due=(int)$q->input('due_day');$policy=(string)$q->input('admission_month_policy');$copies=(string)$q->input('voucher_copies');$methods=array_values(array_unique(array_filter(array_map('trim',explode(',',(string)$q->input('payment_methods'))))));$reminder=$q->input('reminder_enabled')==='1'?1:0;$message=trim((string)$q->input('reminder_message'));$suspend=(int)$q->input('suspend_after_months');$block=(int)$q->input('block_after_months');if($suspend<0||$suspend>24||$block<0||$block>24||($suspend&&$block&&$block<$suspend)){Flash::add('error','Login rules must be 0-24 months, and blocking cannot come before suspension.');return Response::redirect(url('/admin/fees/automation'));}if($day<1||$day>28||($due!==0&&($due<1||$due>28))||!in_array($policy,['current_month','next_month'],true)||!in_array($copies,['single','student_institute','three_copy'],true)||!$methods||mb_strlen($message)>500){Flash::add('error','Enter valid billing settings.');return Response::redirect(url('/admin/fees/automation'));}$now=date('Y-m-d H:i:s');$this->app->database()->query('INSERT INTO fee_settings(institute_id,generation_day,admission_month_policy,due_day,voucher_copies,payment_methods_json,reminder_enabled,reminder_message,updated_by,created_at,updated_at) VALUES(:i,:g,:p,:d,:v,:m,:re,:rm,:u,:c,:n) ON DUPLICATE KEY UPDATE generation_day=VALUES(generation_day),admission_month_policy=VALUES(admission_month_policy),due_day=VALUES(due_day),voucher_copies=VALUES(voucher_copies),payment_methods_json=VALUES(payment_methods_json),reminder_enabled=VALUES(reminder_enabled),reminder_message=VALUES(reminder_message),updated_by=VALUES(updated_by),updated_at=VALUES(updated_at)',['i'=>$this->i(),'g'=>$day,'p'=>$policy,'d'=>$due?:null,'v'=>$copies,'m'=>json_encode($methods,JSON_THROW_ON_ERROR),'re'=>$reminder,'rm'=>$message?:null,'u'=>(int)user()['id'],'c'=>$now,'n'=>$now]);$this->app->database()->query('UPDATE fee_settings SET suspend_after_months=:s,block_after_months=:b WHERE institute_id=:i',['s'=>$suspend,'b'=>$block,'i'=>$this->i()]);Flash::add('success','Fee automation and reminder settings saved.');// Apply the login rule to every student now rather than waiting for the nightly run.
$x=(new \App\Services\AccountAccess($this->app->database()))->evaluateInstitute($this->i());if($x['suspended']||$x['blocked']||$x['restored'])Flash::add('success',"Student logins updated: {$x['suspended']} suspended, {$x['blocked']} blocked, {$x['restored']} restored.");return Response::redirect(url('/admin/fees/automation'));}
public function generate(Request$q):Response{$month=(string)$q->input('month',date('Y-m'));try{$x=(new FeeAutomationService(new FeeRepository($this->app->database()),new StudentRepository($this->app->database())))->generate($this->i(),$month,(int)user()['id'],'manual');Flash::add('success',$x['generated'].' invoice(s) generated; '.$x['skipped'].' already existed.');}catch(\Throwable$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/fees/automation'));}}
